import assert from 'node:assert/strict';
import { Window } from 'happy-dom';
const window = new Window();
for (const key of ['window', 'document', 'Node', 'Element', 'HTMLElement']) globalThis[key] = window[key] ?? window;
const { render } = await import('solid-js/web');
const { createSignal } = await import('solid-js');
const { configure, setLocale } = await import('best-i18n/solid');
const { Words, Rich, Page, Stored, Repeated, Details } = await import('./component.mjs');
const fixed = process.env.STATIC_LOCALE;
const expected = locale => (fixed || locale) === 'zh';
configure({ locales: ['en', 'zh'], baseLocale: 'en' });
const [count, setCount] = createSignal(1);
const [href, setHref] = createSignal('/docs');
const root = document.createElement('div');
const stored = document.createElement('div');
const stopStored = render(Stored, stored);
assert.equal(stored.textContent, expected('en') ? '你好' : 'Hello');
const stop = render(() => [Words(), Rich({ get href() { return href(); } }), Page({ get count() { return count(); } })], root);
assert.equal(root.textContent, expected('en') ? '你好阅读文档。你好1 项阅读文档。' : 'HelloRead docs.HelloOne itemRead docs.');
setLocale('zh');
assert.equal(stored.textContent, expected('zh') ? '你好' : 'Hello');
assert.equal(root.textContent, expected('zh') ? '你好阅读文档。你好1 项阅读文档。' : 'HelloRead docs.HelloOne itemRead docs.');
setCount(2);
setHref('/new');
assert.equal(root.querySelector('span').textContent, expected('zh') ? '2 项' : '2 items');
assert.equal(root.querySelector('a').getAttribute('href'), '/new');
setLocale('en');
assert.equal(root.textContent, expected('en') ? '你好阅读文档。你好2 项阅读文档。' : 'HelloRead docs.Hello2 itemsRead docs.');
stopStored();
stop();
setLocale('zh');
assert.equal(root.textContent, '');
setLocale('en');
const [name, setName] = createSignal('Ada');
let clicks = 0;
const details = document.createElement('div');
document.body.append(details);
const stopDetails = render(() => Details({ get name() { return name(); }, onClick() { clicks++; } }), details);
const repeated = document.createElement('div');
const stopRepeated = render(() => Repeated({ get href() { return href(); } }), repeated);
assert.equal(details.textContent, expected('en') ? '打开欢迎，Ada！你好' : 'OpenHi Ada, welcome!Hello');
setLocale('zh');
setName('Lin');
assert.equal(details.textContent, expected('zh') ? '打开欢迎，Lin！你好' : 'OpenHi Lin, welcome!Hello');
assert.equal(repeated.textContent, expected('zh') ? '阅读文档。阅读文档。' : 'Read docs.Read docs.');
setHref('/changed');
assert.deepEqual([...repeated.querySelectorAll('a')].map(a => a.getAttribute('href')), ['/changed', '/changed']);
assert.equal(details.querySelector('b i').textContent, expected('zh') ? '欢迎' : 'welcome');
details.querySelector('button').click();
assert.equal(clicks, 1);
stopDetails();
details.remove();
stopRepeated();
console.log('ok');
